#[cfg(test)]
pub(crate) fn reset_local_mutation_detail_timings() {
    LAST_LOCAL_MUTATION_DETAIL_TIMINGS.set(LocalMutationDetailTimings::default());
}

#[cfg(test)]
pub(crate) fn last_local_mutation_detail_timings() -> LocalMutationDetailTimings {
    LAST_LOCAL_MUTATION_DETAIL_TIMINGS.get()
}

#[cfg(test)]
fn note_local_mutation_detail(update: impl FnOnce(&mut LocalMutationDetailTimings)) {
    LAST_LOCAL_MUTATION_DETAIL_TIMINGS.with(|timings| {
        let mut current = timings.get();
        update(&mut current);
        timings.set(current);
    });
}

// This is a run-local, authenticated view over the accepted catalog. It is
// deliberately not an object-store, receipt, or projection format.
#[allow(dead_code)]
const CURRENT_PATH_CURSOR_SCHEMA_VERSION: u32 = 2;
const CURRENT_PATH_CATALOG_ROW_SCHEMA_VERSION: u32 = 3;
#[allow(dead_code)]
pub(crate) const MAX_CURRENT_PATH_CURSOR_PAGE_ROWS: usize = 1_024;
#[allow(dead_code)]
pub(crate) const MAX_CURRENT_PATH_CURSOR_PATH_BYTES: usize = 4 * 1024;
#[allow(dead_code)]
pub(crate) const MAX_CURRENT_PATH_CURSOR_PAGE_BYTES: usize = 256 * 1024;
#[allow(dead_code)]
pub(crate) const MAX_CURRENT_PATH_CURSORS: usize = 32;

/// Thread-local causal probe for graph-sized authenticated catalog reads.
///
/// It attributes one catalog traversal between its authenticated trie walk, its
/// per-row path/name/page authority, and the catalog-document shape proof whose
/// cost is linear in the catalog's page entries. `catalog_document_validations`
/// is the structural counter: it must count bounded read windows, never rows,
/// or a graph-sized traversal is quadratic in pages.
///
/// It is thread-local so that one build's structural accounting cannot be
/// perturbed by a concurrent build in the same process. It carries no
/// authority, is never persisted, and is read only by traces and scale tests.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub(crate) struct CurrentPathCursorProbe {
    pub(crate) rows: usize,
    pub(crate) catalog_document_validations: usize,
    /// Total page-map entries visited by those shape validations. Unlike the
    /// call count, this distinguishes many one-page home documents from
    /// repeatedly validating one graph-sized catalog document.
    pub(crate) catalog_entries_validated: usize,
    pub(crate) walk_micros: u128,
    pub(crate) portable_path_micros: u128,
    pub(crate) catalog_state_micros: u128,
    pub(crate) page_name_micros: u128,
}

thread_local! {
    static CURRENT_PATH_CURSOR_PROBE: Cell<CurrentPathCursorProbe> =
        const { Cell::new(CurrentPathCursorProbe {
            rows: 0,
            catalog_document_validations: 0,
            catalog_entries_validated: 0,
            walk_micros: 0,
            portable_path_micros: 0,
            catalog_state_micros: 0,
            page_name_micros: 0,
        }) };
}

fn update_cursor_probe(update: impl FnOnce(&mut CurrentPathCursorProbe)) {
    CURRENT_PATH_CURSOR_PROBE.with(|probe| {
        let mut current = probe.get();
        update(&mut current);
        probe.set(current);
    });
}

fn record_cursor_probe(
    select: impl FnOnce(&mut CurrentPathCursorProbe) -> &mut u128,
    started: std::time::Instant,
) {
    let elapsed = started.elapsed().as_micros();
    update_cursor_probe(|probe| {
        let counter = select(probe);
        *counter = counter.saturating_add(elapsed);
    });
}

/// Read and reset this thread's cursor probe.
pub(crate) fn take_current_path_cursor_probe() -> CurrentPathCursorProbe {
    CURRENT_PATH_CURSOR_PROBE.with(|probe| probe.replace(CurrentPathCursorProbe::default()))
}

/// One exact current page path supplied by the authenticated cursor.
///
/// This semantic row intentionally carries no projected blob or projection
/// generation. The clean runtime joins it to the frontier-matched SQLite
/// projection and reconstructs any projection predecessor from the immutable
/// baseline or accepted manifest tail; no persistent projection-work authority
/// participates in current-path admission.
#[derive(Clone, Debug, Eq, PartialEq)]
#[allow(dead_code)]
pub(crate) struct CurrentPathCatalogRow {
    page_id: PageId,
    path: ManagedPath,
    kind: ManagedTextKind,
    accepted_name_digest: ContentDigest,
}

#[allow(dead_code)]
impl CurrentPathCatalogRow {
    pub(crate) const fn page_id(&self) -> PageId {
        self.page_id
    }

    pub(crate) fn path(&self) -> &ManagedPath {
        &self.path
    }

    pub(crate) const fn kind(&self) -> ManagedTextKind {
        self.kind
    }

    pub(crate) const fn accepted_name_digest(&self) -> ContentDigest {
        self.accepted_name_digest
    }
}

/// Opaque, single-use continuation for an authenticated current-path page.
///
/// The engine-private authority capability makes this intentionally
/// non-serializable and non-forgeable by callers. A cursor dies when its exact
/// accepted frontier changes or when it has been consumed once.
#[allow(dead_code)]
pub(crate) struct CurrentPathCatalogCursor {
    runtime_authority: EngineAuthority,
    binding: CurrentPathCursorBinding,
    cursor_id: u64,
    nonce: u64,
}

/// Constant-size authenticated binding for one current-path cursor epoch.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct CurrentPathCatalogBinding {
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
    accepted_frontier: ContentDigest,
    history_generation: u64,
    history_root: ContentDigest,
    catalog_root: ContentDigest,
    catalog_rows: u64,
}

impl CurrentPathCatalogBinding {
    pub(crate) const fn workspace_id(self) -> WorkspaceId {
        self.workspace_id
    }

    pub(crate) const fn lineage_digest(self) -> LineageDigest {
        self.lineage_digest
    }

    pub(crate) const fn accepted_frontier(self) -> ContentDigest {
        self.accepted_frontier
    }

    #[cfg(test)]
    pub(crate) const fn history_generation(self) -> u64 {
        self.history_generation
    }

    #[cfg(test)]
    pub(crate) const fn history_root(self) -> ContentDigest {
        self.history_root
    }

    #[cfg(test)]
    pub(crate) const fn catalog_root(self) -> ContentDigest {
        self.catalog_root
    }

    pub(crate) const fn catalog_rows(self) -> u64 {
        self.catalog_rows
    }
}

/// One bounded page from [`CurrentPathCatalogCursor`].
#[allow(dead_code)]
pub(crate) struct CurrentPathCatalogPage {
    rows: Vec<CurrentPathCatalogRow>,
    next: Option<CurrentPathCatalogCursor>,
}

#[allow(dead_code)]
impl CurrentPathCatalogPage {
    pub(crate) fn rows(&self) -> &[CurrentPathCatalogRow] {
        &self.rows
    }

    pub(crate) fn has_more(&self) -> bool {
        self.next.is_some()
    }

    pub(crate) fn into_next(self) -> Option<CurrentPathCatalogCursor> {
        self.next
    }

    pub(crate) fn into_parts(
        self,
    ) -> (Vec<CurrentPathCatalogRow>, Option<CurrentPathCatalogCursor>) {
        (self.rows, self.next)
    }
}

