    #[cfg(test)]
    pub fn managed_local_work(&self) -> ManagedLocalWork {
        self.local_overlay.work.get()
    }

    pub fn managed_local_prefix_state(&self) -> ManagedLocalPrefixState {
        ManagedLocalPrefixState {
            next_sequence: self.local_overlay.next_sequence,
            records_applied: self.local_overlay.entries.len(),
            commitment: self.local_overlay.commitment,
        }
    }

    pub(crate) fn managed_local_batch_is_visible(&self, batch_id: BatchId) -> bool {
        self.local_overlay.entry_by_batch.contains_key(&batch_id)
    }

    /// Restore the journal cursor represented by an authenticated drain
    /// checkpoint. Checkpointed records already live in canonical accepted
    /// history, so replaying them into the hot overlay would apply them twice;
    /// nevertheless the next foreground append must continue after that
    /// durable prefix rather than starting again at sequence zero.
    pub(crate) fn resume_checkpointed_managed_local_prefix(
        &mut self,
        next_sequence: u64,
    ) -> Result<(), ManagedLocalRecordError> {
        if self.local_overlay.next_sequence == next_sequence {
            return Ok(());
        }
        if self.local_overlay.next_sequence != 0
            || !self.local_overlay.entries.is_empty()
            || !self.local_overlay.entry_by_batch.is_empty()
            || !self.local_overlay.latest_projection.is_empty()
            || !self.local_overlay.documents.is_empty()
            || !self.local_overlay.document_heads.is_empty()
            || !self.local_overlay.block_claims.is_empty()
        {
            return Err(ManagedLocalRecordError::OutOfOrder {
                expected: self.local_overlay.next_sequence,
                found: next_sequence,
            });
        }
        self.local_overlay.next_sequence = next_sequence;
        self.advance_author_mutation_generation();
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn rewrite_managed_local_authority_endpoint_for_test(
        &mut self,
        sequence: u64,
        batch_id: BatchId,
    ) -> bool {
        let Some(entry) = self
            .local_overlay
            .entries
            .iter_mut()
            .find(|entry| entry.sequence == sequence && entry.batch_id == batch_id)
        else {
            return false;
        };
        let projection = entry
            .projections
            .first_mut()
            .expect("managed-local overlay entry retains a projection");
        let intent = &projection.intent;
        projection.intent = ManifestedProjectionIntent::new(
            intent.workspace_id(),
            intent.source_batch_id(),
            intent.source_author_device_id(),
            intent.source_author_session_id(),
            ProjectionEndpointId::from_uuid(Uuid::from_u128(0xfeed_face)),
            intent.page_id(),
            intent.path().clone(),
            intent.portable_path_index_root(),
            intent.precondition().clone(),
            intent.render_base().cloned(),
            intent.target().clone(),
            intent.post_frontier().clone(),
            intent.claim_evidence().to_vec(),
        )
        .expect("test-only endpoint rewrite retains a valid manifested projection intent");
        true
    }

    #[cfg(test)]
    pub(crate) fn rewrite_managed_local_projection_frontier_with_foreign_document_for_test(
        &mut self,
        sequence: u64,
        batch_id: BatchId,
    ) -> bool {
        let Some(entry) = self
            .local_overlay
            .entries
            .iter_mut()
            .find(|entry| entry.sequence == sequence && entry.batch_id == batch_id)
        else {
            return false;
        };
        let projection = entry
            .projections
            .first_mut()
            .expect("managed-local overlay entry retains a projection");
        let intent = &projection.intent;
        let foreign_document_id = DocumentId::from_uuid(Uuid::from_u128(0xfeed_f00d));
        let mut documents = intent.post_frontier().documents().to_vec();
        documents.push(
            DocumentDependencies::new(foreign_document_id, Vec::new(), vec![batch_id])
                .expect("test-only foreign frontier document is well formed"),
        );
        let frontier = FrontierV2::new(documents)
            .expect("test-only foreign frontier remains canonically ordered");
        projection.intent = ManifestedProjectionIntent::new(
            intent.workspace_id(),
            intent.source_batch_id(),
            intent.source_author_device_id(),
            intent.source_author_session_id(),
            intent.source_endpoint_id(),
            intent.page_id(),
            intent.path().clone(),
            intent.portable_path_index_root(),
            intent.precondition().clone(),
            intent.render_base().cloned(),
            intent.target().clone(),
            frontier,
            intent.claim_evidence().to_vec(),
        )
        .expect("test-only foreign frontier rewrite retains a valid manifested projection intent");
        true
    }

    /// Materialize one exact current path from accepted state plus the
    /// journal-committed local overlay, without SQLite or a graph reload.
    pub fn materialize_current_page_at_path(
        &self,
        path: &ManagedPath,
    ) -> Result<Option<MaterializedPage>, EngineError> {
        let page_id = match self.current_page_at_path(path)? {
            CurrentPageAtPath::ExactOwner(owner) => owner.page_id(),
            CurrentPageAtPath::Released(_)
            | CurrentPageAtPath::Unowned
            | CurrentPageAtPath::PortableCollision(_)
            | CurrentPageAtPath::ReleasedPortableCollision(_) => return Ok(None),
        };
        let page = self.materialize_hot_page_with_overrides(page_id, &BTreeMap::new())?;
        let mut work = self.local_overlay.work.get();
        work.page_materializations = work.page_materializations.saturating_add(1);
        self.local_overlay.work.set(work);
        Ok(Some(page))
    }

    /// Remove the complete pending overlay only after authenticated accepted
    /// state proves the same prefix and exact resulting documents.
    pub(crate) fn collapse_managed_local_prefix(
        &mut self,
        expected_accepted_frontier: &AcceptedFrontierRoot,
    ) -> Result<usize, ManagedLocalRecordError> {
        if &self.accepted_frontier_root()? != expected_accepted_frontier {
            return Err(ManagedLocalRecordError::AcceptedFrontierMismatch);
        }
        if self.local_overlay.entries.is_empty() {
            return Ok(0);
        }
        for entry in &self.local_overlay.entries {
            if !matches!(
                self.archive_status(entry.batch_id)?,
                Some(ArchiveStatus::Accepted { .. })
            ) {
                return Err(ManagedLocalRecordError::AcceptedFrontierMismatch);
            }
        }
        for (document_id, overlay) in &self.local_overlay.documents {
            let accepted = self.clone_visible_document(*document_id, 1)?;
            if DecodedDocumentVersion::of(&accepted) != DecodedDocumentVersion::of(overlay) {
                return Err(ManagedLocalRecordError::AcceptedFrontierMismatch);
            }
        }
        let removed = self.local_overlay.entries.len();
        self.local_overlay.entries.clear();
        self.local_overlay.entry_by_batch.clear();
        self.local_overlay.latest_projection.clear();
        self.local_overlay.documents.clear();
        self.local_overlay.document_heads.clear();
        self.local_overlay.block_claims.clear();
        self.local_overlay.commitment = ContentDigest::of(b"tine/managed-local-prefix/empty/v1\0");
        self.advance_author_mutation_generation();
        Ok(removed)
    }

    pub fn configure_reference_catalog_policy(
        &mut self,
        policy: ReferenceCatalogPolicyV1,
    ) -> Result<(), EngineError> {
        self.ensure_not_blocked()?;
        if self.next_acceptance_sequence != 0 || self.history_generation != 0 {
            return Err(EngineError::ReferenceCatalog(
                "reference policy is immutable after the first accepted frontier".into(),
            ));
        }
        self.reference_catalog_policy = policy;
        self.accepted_frontier_root = empty_accepted_frontier_root();
        self.current_path_catalog.accepted_frontier_root = self.accepted_frontier_root.clone();
        self.current_path_cursor_book.borrow_mut().active.clear();
        Ok(())
    }

    /// Restore the reference extraction policy from an authenticated durable
    /// history record. This is recovery of existing configuration, not a
    /// request to mutate the policy of an accepted frontier.
    fn install_authenticated_reference_catalog_policy(&mut self, policy: ReferenceCatalogPolicyV1) {
        self.reference_catalog_policy = policy;
    }

    pub const fn catalog_document_id(&self) -> DocumentId {
        self.catalog_document_id
    }

    fn replay_timing_enabled(&self) -> bool {
        cfg!(test) || self.activation_trace_enabled
    }

    fn replay_timing_started(&self) -> Option<Instant> {
        self.replay_timing_enabled().then(Instant::now)
    }

    fn record_validation_phase(
        phases: &mut [u128; 10],
        phase: usize,
        started: &mut Option<Instant>,
    ) {
        let Some(phase_started) = started.take() else {
            return;
        };
        let elapsed = phase_started.elapsed();
        phases[phase] = phases[phase].saturating_add(elapsed.as_nanos());
        if super::phase_trace_enabled() {
            eprintln!(
                "PHASE TIME Engine.validate_and_apply.phase_{phase} {:.3}ms",
                elapsed.as_secs_f64() * 1_000.0,
            );
        }
        *started = Some(Instant::now());
    }

    fn record_replay_timing(&self, update: impl FnOnce(&mut ReplayTimingStats)) {
        if !self.replay_timing_enabled() {
            return;
        }
        let mut timing = self.replay_timing.get();
        update(&mut timing);
        self.replay_timing.set(timing);
    }

    fn record_replay_timing_elapsed(
        &self,
        started: Option<Instant>,
        update: impl FnOnce(&mut ReplayTimingStats, u128),
    ) {
        let Some(started) = started else {
            return;
        };
        self.record_replay_timing(|timing| update(timing, started.elapsed().as_nanos()));
    }

