    #[test]
    fn mixed_new_and_existing_shards_do_not_skip_existing_declarations() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(91_500));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(91_501));
        let old_home = DocumentId::from_uuid(Uuid::from_u128(91_502));
        let old_page = PageId::from_uuid(Uuid::from_u128(91_503));
        let old_block = BlockId::from_uuid(Uuid::from_u128(91_504));
        let new_home = DocumentId::from_uuid(Uuid::from_u128(91_505));
        let new_page = PageId::from_uuid(Uuid::from_u128(91_506));
        let new_block = BlockId::from_uuid(Uuid::from_u128(91_507));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"mixed-fast-path"), catalog_id);
        let genesis = engine
            .prepare_bootstrap_transaction(
                test_author(91_510, 1),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: old_page,
                        home_document_id: old_home,
                        name: crate::oplog::LogicalPageName::parse("Existing").unwrap(),
                        path: ManagedPath::parse("pages/Existing.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id: old_block,
                            home_document_id: old_home,
                        },
                        page_id: old_page,
                        parent: None,
                        order: "a".into(),
                        content: "original".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(genesis))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_catalog = engine.clone_visible_document(catalog_id, 2).unwrap();
        let before_old = engine.clone_visible_document(old_home, 2).unwrap();
        let after_catalog = clone_doc(&before_catalog, 2).unwrap();
        insert_page_state(
            &after_catalog,
            new_page,
            &live_page(new_home, "pages/New.md"),
        )
        .unwrap();
        let after_old = clone_doc(&before_old, 2).unwrap();
        block_text(&after_old, old_block)
            .unwrap()
            .update("edited", UpdateOptions::default())
            .unwrap();
        let after_new = LoroDoc::new();
        after_new.set_peer_id(2).unwrap();
        after_new
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, new_page.to_string())
            .unwrap();
        after_new
            .get_map(SHARD_OWNERS)
            .insert(&new_block.to_string(), new_page.to_string())
            .unwrap();
        after_new
            .get_map(SHARD_CONTENT)
            .insert_container(&new_block.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "new")
            .unwrap();
        insert_membership(
            &after_new,
            new_block,
            &MembershipClaim::new(new_home, None, "a").unwrap(),
        )
        .unwrap();
        let before = BTreeMap::from([
            (catalog_id, before_catalog),
            (old_home, before_old),
            (new_home, LoroDoc::new()),
        ]);
        let after = BTreeMap::from([
            (catalog_id, after_catalog),
            (old_home, after_old),
            (new_home, after_new),
        ]);
        let mut effect = derive_effect(catalog_id, &before, &after).unwrap();
        let mut blocks = effect.blocks().to_vec();
        blocks
            .iter_mut()
            .find(|delta| delta.home_document_id == old_home)
            .unwrap()
            .after
            .as_mut()
            .unwrap()
            .content = "incorrect existing declaration".into();
        effect = SemanticEffect::new(
            effect.pages().to_vec(),
            blocks,
            effect.memberships().to_vec(),
        )
        .unwrap();
        let frontier = FrontierV2::new(vec![
            dependencies_for(&engine, catalog_id, 2),
            dependencies_for(&engine, old_home, 2),
        ])
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(91_511, 2),
            &before,
            &after,
            frontier,
            effect,
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::SemanticEffectMismatch,
                ..
            }
        ));
        assert_eq!(
            engine.materialize_page(old_page).unwrap().blocks[0].content,
            "original"
        );
        assert!(matches!(
            engine.materialize_page(new_page),
            Err(EngineError::PageNotFound(_))
        ));
    }

    #[test]
    fn crdt_witness_decode_rejects_duplicate_unsorted_and_noncanonical_heads() {
        let batch_id = BatchId::from_uuid(Uuid::from_u128(45));
        let document_id = DocumentId::from_uuid(Uuid::from_u128(46));
        let head_a = BatchId::from_uuid(Uuid::from_u128(47));
        let head_b = BatchId::from_uuid(Uuid::from_u128(48));
        for dependency_heads in [vec![head_a, head_a], vec![head_b, head_a]] {
            let bytes = postcard::to_allocvec(&CrdtUpdatePayload {
                schema_version: CRDT_UPDATE_PAYLOAD_SCHEMA_VERSION,
                batch_id,
                document_id,
                dependency_heads,
                batch_dependency_heads: vec![head_a],
                causal_state_digest: None,
                raw_update: vec![1],
            })
            .unwrap();
            assert!(matches!(
                decode_crdt_update_payload(batch_id, document_id, &bytes),
                Err(EngineError::InvalidCrdt(_))
            ));
        }

        let mut canonical = encode_crdt_update_payload(
            batch_id,
            document_id,
            vec![head_a],
            vec![head_a],
            None,
            vec![1],
        )
        .unwrap();
        canonical.push(0);
        assert!(matches!(
            decode_crdt_update_payload(batch_id, document_id, &canonical),
            Err(EngineError::InvalidCrdt(_))
        ));

        let future = postcard::to_allocvec(&CrdtUpdatePayload {
            schema_version: CRDT_UPDATE_PAYLOAD_SCHEMA_VERSION + 1,
            batch_id,
            document_id,
            dependency_heads: vec![head_a],
            batch_dependency_heads: vec![head_a],
            causal_state_digest: None,
            raw_update: vec![1],
        })
        .unwrap();
        assert!(matches!(
            decode_crdt_update_payload(batch_id, document_id, &future),
            Err(EngineError::InvalidCrdt(_))
        ));
    }

    #[test]
    fn malformed_and_referentially_incomplete_replacements_reject_atomically() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(1));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(2));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(20));
        let page_id = PageId::from_uuid(Uuid::from_u128(10));
        let block_id = BlockId::from_uuid(Uuid::from_u128(30));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"lineage"), catalog_id);

        let catalog = LoroDoc::new();
        catalog.set_peer_id(50).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/A.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let shard = LoroDoc::new();
        shard.set_peer_id(50).unwrap();
        shard
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_id.to_string())
            .unwrap();
        shard
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "coherent content without page identity")
            .unwrap();

        let before = BTreeMap::from([(catalog_id, LoroDoc::new()), (home_id, LoroDoc::new())]);
        let after = BTreeMap::from([(catalog_id, catalog), (home_id, shard)]);
        let batch = validated_transition(
            &engine,
            test_author(50, 50),
            &before,
            &after,
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.canonical_snapshot().unwrap().pages.is_empty());
        assert!(engine.visible_documents.is_empty());

        let catalog_only = LoroDoc::new();
        catalog_only.set_peer_id(51).unwrap();
        insert_page_state(
            &catalog_only,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Catalog Only.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let catalog_only = validated_transition(
            &engine,
            test_author(51, 51),
            &BTreeMap::from([(catalog_id, LoroDoc::new())]),
            &BTreeMap::from([(catalog_id, catalog_only)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(catalog_only).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        let orphan_shard = LoroDoc::new();
        orphan_shard.set_peer_id(52).unwrap();
        orphan_shard
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        let orphan_shard = validated_transition(
            &engine,
            test_author(52, 52),
            &BTreeMap::from([(home_id, LoroDoc::new())]),
            &BTreeMap::from([(home_id, orphan_shard)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(orphan_shard).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        let missing_home_id = DocumentId::from_uuid(Uuid::from_u128(21));
        let referenced_block_id = BlockId::from_uuid(Uuid::from_u128(31));
        let catalog = LoroDoc::new();
        catalog.set_peer_id(53).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Missing Home.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let shard = LoroDoc::new();
        shard.set_peer_id(53).unwrap();
        shard
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        insert_membership(
            &shard,
            referenced_block_id,
            &MembershipClaim::new(missing_home_id, None, "a").unwrap(),
        )
        .unwrap();
        let missing_home = validated_transition(
            &engine,
            test_author(53, 53),
            &BTreeMap::from([(catalog_id, LoroDoc::new()), (home_id, LoroDoc::new())]),
            &BTreeMap::from([(catalog_id, catalog), (home_id, shard)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(missing_home).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        // None of the ordinary validation failures above may leave provisional
        // immutable-home evidence behind. The same identities remain valid for
        // a later coherent batch.
        let coherent = engine
            .prepare_bootstrap_transaction(
                test_author(54, 54),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id,
                        home_document_id: home_id,
                        name: crate::oplog::LogicalPageName::parse("Coherent").unwrap(),
                        path: ManagedPath::parse("pages/Coherent.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id: home_id,
                        },
                        page_id,
                        parent: None,
                        order: "a".into(),
                        content: "accepted after ordinary rejections".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(coherent))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));
        assert!(engine.fatal_evidence().is_none());
        assert_eq!(
            engine.materialize_page(page_id).unwrap().blocks[0].content,
            "accepted after ordinary rejections"
        );
    }

    #[test]
    fn raw_catalog_cannot_smuggle_shard_state_past_the_semantic_effect() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(61));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(62));
        let page_id = PageId::from_uuid(Uuid::from_u128(63));
        let block_id = BlockId::from_uuid(Uuid::from_u128(64));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"disjoint-roles"), catalog_id);

        let catalog = LoroDoc::new();
        catalog.set_peer_id(65).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Aliased.md").unwrap(),
                home_document_id: catalog_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        catalog
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        catalog
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_id.to_string())
            .unwrap();
        catalog
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "semantically omitted content")
            .unwrap();
        insert_membership(
            &catalog,
            block_id,
            &MembershipClaim::new(catalog_id, None, "a").unwrap(),
        )
        .unwrap();

        let before = BTreeMap::from([(catalog_id, LoroDoc::new())]);
        let after = BTreeMap::from([(catalog_id, catalog)]);
        let declared_page_only_effect = SemanticEffect::new(
            vec![PageDelta {
                page_id,
                before: None,
                after: Some(PageState::Live {
                    name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                    path: ManagedPath::parse("pages/Aliased.md").unwrap(),
                    home_document_id: catalog_id,
                    kind: ManagedTextKind::Page,
                }),
            }],
            Vec::new(),
            Vec::new(),
        )
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(65, 65),
            &before,
            &after,
            FrontierV2::new(Vec::new()).unwrap(),
            declared_page_only_effect,
        );
        let outcome = engine.stage_ready(batch);
        assert!(
            matches!(
                outcome.disposition(),
                BatchDisposition::Rejected {
                    error: EngineError::MalformedDocument { .. },
                    ..
                }
            ),
            "unexpected aliased-role outcome: {outcome:?}"
        );
        assert!(engine.canonical_snapshot().unwrap().pages.is_empty());
        assert!(engine.visible_documents.is_empty());
    }

    #[test]
    fn accepted_shard_page_identity_cannot_change() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(101));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(102));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(120));
        let page_a = PageId::from_uuid(Uuid::from_u128(110));
        let page_b = PageId::from_uuid(Uuid::from_u128(111));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"identity"), catalog_id);
        let genesis = engine
            .prepare_bootstrap_transaction(
                test_author(200, 200),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: page_a,
                    home_document_id: home_id,
                    name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                    path: ManagedPath::parse("pages/A.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(genesis))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_doc = engine.clone_visible_document(home_id, 201).unwrap();
        let changed = clone_doc(&before_doc, 201).unwrap();
        changed
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_b.to_string())
            .unwrap();
        let before = BTreeMap::from([(home_id, before_doc)]);
        let after = BTreeMap::from([(home_id, changed)]);
        let dependencies = DocumentDependencies::new(
            home_id,
            canonical_peer_counters(&before[&home_id].oplog_vv()).unwrap(),
            engine
                .document_dependency_heads(home_id, false)
                .unwrap()
                .into_iter()
                .collect(),
        )
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(201, 201),
            &before,
            &after,
            FrontierV2::new(vec![dependencies]).unwrap(),
            SemanticEffect::new(Vec::new(), Vec::new(), Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::ShardPageIdentityChanged { .. }
                    | EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert_eq!(engine.materialize_page(page_a).unwrap().page_id, page_a);
    }

    #[test]
    fn raw_block_removal_rejects_before_merge_in_both_delivery_orders() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(301));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(302));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(320));
        let page_id = PageId::from_uuid(Uuid::from_u128(310));
        let block_id = BlockId::from_uuid(Uuid::from_u128(330));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"merged-residue"), catalog_id);
        let genesis = engine
            .prepare_bootstrap_transaction(
                test_author(400, 400),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id,
                        home_document_id: home_id,
                        name: crate::oplog::LogicalPageName::parse("Merge").unwrap(),
                        path: ManagedPath::parse("pages/Merge.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id: home_id,
                        },
                        page_id,
                        parent: None,
                        order: "a".into(),
                        content: "baseline".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        let genesis = ValidatedBatch::new(genesis);
        assert!(matches!(
            engine.stage_ready(genesis.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let dependencies = DocumentDependencies::new(
            home_id,
            canonical_peer_counters(
                &engine
                    .clone_visible_document(home_id, 401)
                    .unwrap()
                    .oplog_vv(),
            )
            .unwrap(),
            engine
                .document_dependency_heads(home_id, false)
                .unwrap()
                .into_iter()
                .collect(),
        )
        .unwrap();
        let frontier = FrontierV2::new(vec![dependencies]).unwrap();

        let removed_before = engine.clone_visible_document(home_id, 401).unwrap();
        let removed_after = clone_doc(&removed_before, 401).unwrap();
        removed_after
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        removed_after
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        removed_after
            .get_map(SHARD_MEMBERS)
            .delete(&block_id.to_string())
            .unwrap();
        let before_state = read_block_state(home_id, &removed_before, block_id)
            .unwrap()
            .unwrap();
        let removed_effect = raw_semantic_effect(
            Vec::new(),
            vec![BlockDelta {
                block_id,
                home_document_id: home_id,
                before: Some(before_state),
                after: None,
            }],
            vec![MembershipDelta {
                page_id,
                block_id,
                before: Some(MembershipClaim::new(home_id, None, "a").unwrap()),
                after: None,
            }],
        );
        let removed = validated_transition_with_payload(
            &engine,
            test_author(401, 401),
            &BTreeMap::from([(home_id, removed_before)]),
            &BTreeMap::from([(home_id, removed_after)]),
            frontier.clone(),
            removed_effect,
        );

        let edited_before = engine.clone_visible_document(home_id, 402).unwrap();
        let edited_after = clone_doc(&edited_before, 402).unwrap();
        edited_after
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        edited_after
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "concurrent replacement")
            .unwrap();
        let edited = validated_transition(
            &engine,
            test_author(402, 402),
            &BTreeMap::from([(home_id, edited_before)]),
            &BTreeMap::from([(home_id, edited_after)]),
            frontier,
        );

        let mut expected_accepted = None;
        let mut expected_rejected = None;
        let mut expected_snapshot = None;
        for removal_first in [true, false] {
            let mut receiver =
                ShardedHotEngine::new(workspace, LineageDigest::of(b"merged-residue"), catalog_id);
            assert!(matches!(
                receiver.stage_ready(genesis.clone()).disposition(),
                BatchDisposition::Accepted { .. }
            ));
            let ordered = if removal_first {
                [removed.clone(), edited.clone()]
            } else {
                [edited.clone(), removed.clone()]
            };
            let mut rejected = Vec::new();
            for batch in ordered {
                let batch_id = batch.manifest().batch_id();
                if matches!(
                    receiver.stage_ready(batch).disposition(),
                    BatchDisposition::Rejected { .. }
                ) {
                    rejected.push(batch_id);
                }
            }
            let accepted = receiver.status().accepted_batch_ids().unwrap();
            let snapshot = receiver.canonical_snapshot().unwrap();
            assert_eq!(
                receiver.materialize_page(page_id).unwrap().blocks[0].content,
                "concurrent replacement"
            );
            if let Some(expected) = &expected_accepted {
                assert_eq!(&accepted, expected);
                assert_eq!(&rejected, expected_rejected.as_ref().unwrap());
                assert_eq!(&snapshot, expected_snapshot.as_ref().unwrap());
            } else {
                expected_accepted = Some(accepted);
                expected_rejected = Some(rejected);
                expected_snapshot = Some(snapshot);
            }
        }
        assert_eq!(
            expected_accepted.unwrap(),
            vec![
                BatchId::from_uuid(Uuid::from_u128(400)),
                BatchId::from_uuid(Uuid::from_u128(402)),
            ]
        );
        assert_eq!(
            expected_rejected.unwrap(),
            vec![BatchId::from_uuid(Uuid::from_u128(401))]
        );
    }

    #[test]
    fn existing_block_id_cannot_be_duplicated_or_recreated_in_another_home() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(501));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(502));
        let home_a = DocumentId::from_uuid(Uuid::from_u128(520));
        let home_b = DocumentId::from_uuid(Uuid::from_u128(521));
        let page_a = PageId::from_uuid(Uuid::from_u128(510));
        let page_b = PageId::from_uuid(Uuid::from_u128(511));
        let block_id = BlockId::from_uuid(Uuid::from_u128(530));
        let lineage = LineageDigest::of(b"immutable-block-home");
        let mut engine = ShardedHotEngine::new(workspace, lineage, catalog_id);
        let genesis = ValidatedBatch::new(
            engine
                .prepare_bootstrap_transaction(
                    test_author(600, 600),
                    &OperationTransaction::new(vec![
                        SemanticOperation::CreatePage {
                            page_id: page_a,
                            home_document_id: home_a,
                            name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                            path: ManagedPath::parse("pages/A.md").unwrap(),
                            kind: ManagedTextKind::Page,
                        },
                        SemanticOperation::CreatePage {
                            page_id: page_b,
                            home_document_id: home_b,
                            name: crate::oplog::LogicalPageName::parse("B").unwrap(),
                            path: ManagedPath::parse("pages/B.md").unwrap(),
                            kind: ManagedTextKind::Page,
                        },
                        SemanticOperation::CreateBlock {
                            block: BlockLocation {
                                block_id,
                                home_document_id: home_a,
                            },
                            page_id: page_a,
                            parent: None,
                            order: "a".into(),
                            content: "immutable home A".into(),
                        },
                    ])
                    .unwrap(),
                )
                .unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(genesis.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let duplicate_before = engine.clone_visible_document(home_b, 601).unwrap();
        let duplicate_after = clone_doc(&duplicate_before, 601).unwrap();
        duplicate_after
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_b.to_string())
            .unwrap();
        duplicate_after
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&block_id.to_string())
            .unwrap()
            .insert(0, "duplicate home B")
            .unwrap();
        insert_membership(
            &duplicate_after,
            block_id,
            &MembershipClaim::new(home_b, None, "b").unwrap(),
        )
        .unwrap();
        let duplicate_author = test_author(601, 601);
        let duplicate = validated_transition(
            &engine,
            duplicate_author,
            &BTreeMap::from([(home_b, duplicate_before)]),
            &BTreeMap::from([(home_b, duplicate_after)]),
            FrontierV2::new(vec![dependencies_for(&engine, home_b, 601)]).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(duplicate).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::BlockAlreadyExists(found),
                ..
            } if found == block_id
        ));
        assert_eq!(engine.fatal_evidence(), None);

        for (home_document_id, page_id) in [(home_a, page_a), (home_b, page_b)] {
            assert!(matches!(
                engine.prepare_bootstrap_transaction(
                    test_author(603, 603),
                    &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id,
                        },
                        page_id,
                        parent: None,
                        order: "c".into(),
                        content: "author must consult global immutable-home evidence".into(),
                    }])
                    .unwrap(),
                ),
                Err(EngineError::BlockAlreadyExists(found)) if found == block_id
            ));
        }

        let same_batch_id = BlockId::from_uuid(Uuid::from_u128(531));
        let same_before_a = engine.clone_visible_document(home_a, 604).unwrap();
        let same_before_b = engine.clone_visible_document(home_b, 604).unwrap();
        let same_after_a = clone_doc(&same_before_a, 604).unwrap();
        let same_after_b = clone_doc(&same_before_b, 604).unwrap();
        for (document_id, page_id, document, order) in [
            (home_a, page_a, &same_after_a, "same-a"),
            (home_b, page_b, &same_after_b, "same-b"),
        ] {
            document
                .get_map(SHARD_OWNERS)
                .insert(&same_batch_id.to_string(), page_id.to_string())
                .unwrap();
            document
                .get_map(SHARD_CONTENT)
                .ensure_mergeable_text(&same_batch_id.to_string())
                .unwrap()
                .insert(0, order)
                .unwrap();
            insert_membership(
                document,
                same_batch_id,
                &MembershipClaim::new(document_id, None, order).unwrap(),
            )
            .unwrap();
        }
        let same_batch_duplicate = validated_transition(
            &engine,
            test_author(604, 604),
            &BTreeMap::from([(home_a, same_before_a), (home_b, same_before_b)]),
            &BTreeMap::from([(home_a, same_after_a), (home_b, same_after_b)]),
            FrontierV2::new(vec![
                dependencies_for(&engine, home_a, 604),
                dependencies_for(&engine, home_b, 604),
            ])
            .unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(same_batch_duplicate).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::BlockAlreadyExists(found),
            } if found == same_batch_id
        ));
        assert_eq!(engine.fatal_evidence(), None);
        assert!(engine
            .recover_block_state(home_a, same_batch_id)
            .unwrap()
            .is_none());
        assert!(engine
            .recover_block_state(home_b, same_batch_id)
            .unwrap()
            .is_none());
        let accepted_after_rollback = engine
            .prepare_bootstrap_transaction(
                test_author(605, 605),
                &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id: same_batch_id,
                        home_document_id: home_a,
                    },
                    page_id: page_a,
                    parent: None,
                    order: "accepted-after-rollback".into(),
                    content: "no provisional identity evidence remained".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(accepted_after_rollback))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let mut relocation_engine = ShardedHotEngine::new(workspace, lineage, catalog_id);
        assert!(matches!(
            relocation_engine.stage_ready(genesis).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_a = relocation_engine
            .clone_visible_document(home_a, 602)
            .unwrap();
        let before_b = relocation_engine
            .clone_visible_document(home_b, 602)
            .unwrap();
        let after_a = clone_doc(&before_a, 602).unwrap();
        after_a
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        after_a
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        after_a
            .get_map(SHARD_MEMBERS)
            .delete(&block_id.to_string())
            .unwrap();
        let after_b = clone_doc(&before_b, 602).unwrap();
        after_b
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_b.to_string())
            .unwrap();
        after_b
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&block_id.to_string())
            .unwrap()
            .insert(0, "recreated home B")
            .unwrap();
        insert_membership(
            &after_b,
            block_id,
            &MembershipClaim::new(home_b, None, "b").unwrap(),
        )
        .unwrap();
        let removed_state = read_block_state(home_a, &before_a, block_id)
            .unwrap()
            .unwrap();
        let recreated_state = read_block_state(home_b, &after_b, block_id)
            .unwrap()
            .unwrap();
        let relocation_effect = raw_semantic_effect(
            Vec::new(),
            vec![
                BlockDelta {
                    block_id,
                    home_document_id: home_a,
                    before: Some(removed_state),
                    after: None,
                },
                BlockDelta {
                    block_id,
                    home_document_id: home_b,
                    before: None,
                    after: Some(recreated_state),
                },
            ],
            vec![
                MembershipDelta {
                    page_id: page_a,
                    block_id,
                    before: Some(MembershipClaim::new(home_a, None, "a").unwrap()),
                    after: None,
                },
                MembershipDelta {
                    page_id: page_b,
                    block_id,
                    before: None,
                    after: Some(MembershipClaim::new(home_b, None, "b").unwrap()),
                },
            ],
        );
        let relocation = validated_transition_with_payload(
            &relocation_engine,
            test_author(602, 602),
            &BTreeMap::from([(home_a, before_a), (home_b, before_b)]),
            &BTreeMap::from([(home_a, after_a), (home_b, after_b)]),
            FrontierV2::new(vec![
                dependencies_for(&relocation_engine, home_a, 602),
                dependencies_for(&relocation_engine, home_b, 602),
            ])
            .unwrap(),
            relocation_effect,
        );
        assert!(matches!(
            relocation_engine.stage_ready(relocation).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::Semantic(_),
                ..
            }
        ));
        assert_eq!(
            relocation_engine.materialize_page(page_a).unwrap().blocks[0].content,
            "immutable home A"
        );
        assert!(relocation_engine
            .materialize_page(page_b)
            .unwrap()
            .blocks
            .is_empty());
        assert!(relocation_engine
            .recover_block_state(home_b, block_id)
            .unwrap()
            .is_none());
    }

    #[test]
    fn compact_direct_parent_preserves_cross_document_atomic_ancestry() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(7_000));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(7_001));
        let page_a = PageId::from_uuid(Uuid::from_u128(7_002));
        let page_b = PageId::from_uuid(Uuid::from_u128(7_003));
        let page_c = PageId::from_uuid(Uuid::from_u128(7_004));
        let home_a = DocumentId::from_uuid(Uuid::from_u128(7_005));
        let home_b = DocumentId::from_uuid(Uuid::from_u128(7_006));
        let home_c = DocumentId::from_uuid(Uuid::from_u128(7_007));
        let duplicate = BlockId::from_uuid(Uuid::from_u128(7_008));
        let support = BlockId::from_uuid(Uuid::from_u128(7_009));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"cross-document"), catalog);
        let genesis = engine
            .prepare_bootstrap_transaction(
                test_author(7_010, 710),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: page_a,
                        home_document_id: home_a,
                        name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                        path: ManagedPath::parse("pages/A.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: page_b,
                        home_document_id: home_b,
                        name: crate::oplog::LogicalPageName::parse("B").unwrap(),
                        path: ManagedPath::parse("pages/B.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: page_c,
                        home_document_id: home_c,
                        name: crate::oplog::LogicalPageName::parse("C").unwrap(),
                        path: ManagedPath::parse("pages/C.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(genesis));
        let ancestor = engine
            .prepare_bootstrap_transaction(
                test_author(7_011, 711),
                &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id: duplicate,
                        home_document_id: home_a,
                    },
                    page_id: page_a,
                    parent: None,
                    order: "a".into(),
                    content: "ancestor identity".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(ancestor));
        let atomic_parent = engine
            .prepare_bootstrap_transaction(
                test_author(7_012, 712),
                &OperationTransaction::new(vec![
                    SemanticOperation::EditBlockContent {
                        block: BlockLocation {
                            block_id: duplicate,
                            home_document_id: home_a,
                        },
                        content: "parent touched ancestor document".into(),
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id: support,
                            home_document_id: home_b,
                        },
                        page_id: page_b,
                        parent: None,
                        order: "support".into(),
                        content: "parent also touched child document".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(atomic_parent));

        let authored_descendant = engine
            .prepare_bootstrap_transaction(
                test_author(7_014, 714),
                &OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
                    block: BlockLocation {
                        block_id: support,
                        home_document_id: home_b,
                    },
                    content: "legitimate cross-document descendant".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(authored_descendant
            .manifest()
            .dependency_frontier()
            .documents()
            .iter()
            .any(|entry| {
                entry.document_id() == home_b
                    && entry.direct_dependency_heads()
                        == [BatchId::from_uuid(Uuid::from_u128(7_012))]
            }));
        assert!(!authored_descendant
            .manifest()
            .dependency_frontier()
            .documents()
            .iter()
            .any(|entry| entry.document_id() == home_a));

        let before_c = engine.clone_visible_document(home_c, 713).unwrap();
        let after_c = clone_doc(&before_c, 713).unwrap();
        after_c
            .get_map(SHARD_OWNERS)
            .insert(&duplicate.to_string(), page_c.to_string())
            .unwrap();
        after_c
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&duplicate.to_string())
            .unwrap()
            .insert(0, "omitted cross-document ancestor")
            .unwrap();
        insert_membership(
            &after_c,
            duplicate,
            &MembershipClaim::new(home_c, None, "duplicate").unwrap(),
        )
        .unwrap();
        let malformed = validated_transition(
            &engine,
            test_author(7_013, 713),
            &BTreeMap::from([(home_c, before_c)]),
            &BTreeMap::from([(home_c, after_c)]),
            FrontierV2::new(vec![
                dependencies_for(&engine, home_b, 713),
                dependencies_for(&engine, home_c, 713),
            ])
            .unwrap(),
        );
        let malformed_outcome = engine.stage_ready(malformed).disposition();
        assert!(
            matches!(
                malformed_outcome,
                BatchDisposition::Rejected {
                    error: EngineError::BlockAlreadyExists(found),
                }
                if found == duplicate
            ),
            "unexpected malformed ancestry outcome: {malformed_outcome:?}"
        );
        assert_eq!(engine.fatal_evidence(), None);
    }

    #[test]
    fn sequential_same_page_chain_has_bounded_authorship_manifest_and_stage_work() {
        const BATCHES: usize = 192;
        const MAX_COMPACT_MANIFEST_BYTES: usize = 4_096;
        const MAX_HISTORY_INDEX_READS_PER_STAGE: usize = 100;
        const MAX_HISTORY_INDEX_WRITES_PER_STAGE: usize = 33;
        const MAX_HISTORY_RECORD_READS_PER_STAGE: usize = 1;

        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(8_000));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(8_001));
        let page = PageId::from_uuid(Uuid::from_u128(8_002));
        let home = DocumentId::from_uuid(Uuid::from_u128(8_003));
        let block = BlockId::from_uuid(Uuid::from_u128(8_004));
        let lineage = LineageDigest::of(b"bounded-batch-history");
        let root =
            std::env::temp_dir().join(format!("tine-oplog-bounded-history-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let archive_path = root.join("archive");
        let writer = ObjectStore::open(&archive_path, workspace).unwrap();
        let reader = ObjectStore::open(&archive_path, workspace).unwrap();
        let mut engine = ShardedHotEngine::with_archive_store(reader, lineage, catalog);
        let mut max_candidate_visits = 0;
        let mut max_status_lookups = 0;
        let mut late_manifest_sizes = Vec::new();
        let mut early_stage_costs = Vec::<[usize; 10]>::new();
        let mut late_stage_costs = Vec::<[usize; 10]>::new();
        let mut early_author_clone_costs = Vec::<[usize; 2]>::new();
        let mut late_author_clone_costs = Vec::<[usize; 2]>::new();

        for index in 0..BATCHES {
            let operation = if index == 0 {
                vec![
                    SemanticOperation::CreatePage {
                        page_id: page,
                        home_document_id: home,
                        name: crate::oplog::LogicalPageName::parse("History").unwrap(),
                        path: ManagedPath::parse("pages/History.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id: block,
                            home_document_id: home,
                        },
                        page_id: page,
                        parent: None,
                        order: "a".into(),
                        content: "0".into(),
                    },
                ]
            } else {
                vec![SemanticOperation::EditBlockContent {
                    block: BlockLocation {
                        block_id: block,
                        home_document_id: home,
                    },
                    content: index.to_string(),
                }]
            };
            let prepare_before = engine.instrumentation();
            let prepared = engine
                .prepare_bootstrap_transaction(
                    // A device keeps one stable Loro peer for its sequential
                    // edits. Peer cardinality is a separate legitimate
                    // frontier dimension and is not page-history growth.
                    test_author(8_100 + index as u128, 8_100),
                    &OperationTransaction::new(operation).unwrap(),
                )
                .unwrap();
            let prepare_after = engine.instrumentation();
            assert_eq!(
                prepare_after.prepare_transactions - prepare_before.prepare_transactions,
                1
            );
            assert!(
                prepare_after.prepare_document_head_visits
                    - prepare_before.prepare_document_head_visits
                    <= 2
            );
            let accepted_manifest_reads = prepare_after.store.accepted_manifest_reads
                - prepare_before.store.accepted_manifest_reads;
            assert!(
                accepted_manifest_reads <= 2,
                "ordinary authorship used {accepted_manifest_reads} archive reads at batch {index}"
            );
            assert!(
                prepare_after.store.dag_manifest_reads - prepare_before.store.dag_manifest_reads
                    <= 2,
                "ordinary authorship exceeded its bounded DAG-read ceiling at batch {index}"
            );
            let author_clone_cost = [
                prepare_after.author_snapshot_clones - prepare_before.author_snapshot_clones,
                prepare_after.author_snapshot_clone_ops - prepare_before.author_snapshot_clone_ops,
            ];
            if index < 16 {
                early_author_clone_costs.push(author_clone_cost);
            }
            if index >= BATCHES - 16 {
                late_author_clone_costs.push(author_clone_cost);
            }
            let manifest_size = prepared.manifest().encode().unwrap().len();
            assert!(
                manifest_size <= MAX_COMPACT_MANIFEST_BYTES,
                "manifest {index} is {manifest_size} bytes"
            );
            if index >= BATCHES - 16 {
                late_manifest_sizes.push(manifest_size);
            }
            writer
                .publish_bootstrap_prepared_for_test(&prepared)
                .unwrap();
            let work_before = engine.history_work.get();
            let stage_before = engine.instrumentation();
            assert!(matches!(
                engine
                    .stage_archive_batch(prepared.manifest().batch_id())
                    .unwrap()
                    .disposition(),
                BatchDisposition::Accepted { .. }
            ));
            let work_after = engine.history_work.get();
            let stage_after = engine.instrumentation();
            assert_eq!(
                stage_after.store.directory_enumerations
                    - stage_before.store.directory_enumerations,
                0,
                "stage {index} enumerated an object-store directory"
            );
            assert!(
                stage_after.store.dag_manifest_reads - stage_before.store.dag_manifest_reads <= 2,
                "exact-current stage {index} exceeded its bounded DAG-read ceiling"
            );
            assert!(
                stage_after.store.history_index_reads - stage_before.store.history_index_reads
                    <= MAX_HISTORY_INDEX_READS_PER_STAGE,
                "stage {index} exceeded the authenticated point-lookup read bound: {} reads",
                stage_after.store.history_index_reads - stage_before.store.history_index_reads
            );
            assert!(
                stage_after.store.history_index_writes - stage_before.store.history_index_writes
                    <= MAX_HISTORY_INDEX_WRITES_PER_STAGE,
                "stage {index} exceeded the authenticated index write bound"
            );
            assert!(
                stage_after.store.history_record_reads - stage_before.store.history_record_reads
                    <= MAX_HISTORY_RECORD_READS_PER_STAGE,
                "stage {index} exceeded the terminal-record read bound"
            );
            assert!(
                stage_after.store.history_decodes - stage_before.store.history_decodes
                    <= MAX_HISTORY_RECORD_READS_PER_STAGE,
                "stage {index} exceeded the terminal-record decode bound"
            );
            max_candidate_visits = max_candidate_visits.max(
                work_after
                    .drain_candidate_visits
                    .saturating_sub(work_before.drain_candidate_visits),
            );
            max_status_lookups = max_status_lookups.max(
                work_after
                    .dependency_status_lookups
                    .saturating_sub(work_before.dependency_status_lookups),
            );
            let stage_cost = [
                stage_after.store.history_index_reads - stage_before.store.history_index_reads,
                stage_after.store.history_index_writes - stage_before.store.history_index_writes,
                stage_after.store.history_record_reads - stage_before.store.history_record_reads,
                stage_after.store.history_decodes - stage_before.store.history_decodes,
                stage_after.store.dag_manifest_reads - stage_before.store.dag_manifest_reads,
                work_after
                    .drain_candidate_visits
                    .saturating_sub(work_before.drain_candidate_visits),
                work_after
                    .dependency_status_lookups
                    .saturating_sub(work_before.dependency_status_lookups),
                stage_after.stage_snapshot_clones - stage_before.stage_snapshot_clones,
                stage_after.stage_snapshot_clone_ops - stage_before.stage_snapshot_clone_ops,
                stage_after.stage_structural_buffer_reuses
                    - stage_before.stage_structural_buffer_reuses,
            ];
            if index < 16 {
                early_stage_costs.push(stage_cost);
            }
            if index >= BATCHES - 16 {
                late_stage_costs.push(stage_cost);
            }
        }

        let component_max = |costs: &[[usize; 10]]| {
            costs.iter().fold([0; 10], |mut maxima, cost| {
                for (maximum, value) in maxima.iter_mut().zip(cost) {
                    *maximum = (*maximum).max(*value);
                }
                maxima
            })
        };
        let early_max = component_max(&early_stage_costs);
        let late_max = component_max(&late_stage_costs);
        assert!(
            late_max
                .iter()
                .zip(early_max)
                .all(|(late, early)| *late <= early),
            "late point/DAG/status work grew with page age: early={early_max:?}, late={late_max:?}"
        );
        eprintln!("compact_history_stage_cost early_max={early_max:?} late_max={late_max:?}");
        let component_max_2 = |costs: &[[usize; 2]]| {
            costs.iter().fold([0; 2], |mut maxima, cost| {
                for (maximum, value) in maxima.iter_mut().zip(cost) {
                    *maximum = (*maximum).max(*value);
                }
                maxima
            })
        };
        let early_author_max = component_max_2(&early_author_clone_costs);
        let late_author_max = component_max_2(&late_author_clone_costs);
        assert!(
            late_author_max
                .iter()
                .zip(early_author_max)
                .all(|(late, early)| *late <= early),
            "late author snapshot/history work grew with page age: early={early_author_max:?}, late={late_author_max:?}"
        );
        assert!(
            late_manifest_sizes.iter().copied().max().unwrap()
                - late_manifest_sizes.iter().copied().min().unwrap()
                <= 64,
            "late compact manifest sizes grew with page age: {late_manifest_sizes:?}"
        );

        assert!(
            engine.archive_fingerprints.len() <= 4,
            "finalized fingerprints remained hot: {}",
            engine.archive_fingerprints.len()
        );
        assert!(
            engine.persisted_staged.len() <= 4,
            "persisted batch IDs remained hot: {}",
            engine.persisted_staged.len()
        );
        assert!(
            engine.statuses.len() <= 4,
            "finalized statuses remained hot: {}",
            engine.statuses.len()
        );
        assert!(
            engine
                .visible_document_heads
                .values()
                .map(BTreeSet::len)
                .sum::<usize>()
                <= 8,
            "document direct-head frontier exceeded its compact bound"
        );
        assert!(
            engine.accepted_frontier.is_empty(),
            "store-backed accepted frontier leaked into graph-wide heap state"
        );
        assert!(
            engine.accepted_sequence.is_empty(),
            "store-backed accepted sequence index leaked into graph-wide heap state"
        );
        let exact_frontier = engine.exact_frontier().unwrap();
        assert_eq!(exact_frontier.documents().len(), 2);
        let exact_tips = exact_frontier
            .documents()
            .iter()
            .flat_map(|document| document.direct_dependency_heads().iter().copied())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        assert_eq!(engine.accepted_frontier_tip_batches().unwrap(), exact_tips);
        assert!(
            max_candidate_visits <= 2,
            "one stage revisited {max_candidate_visits} active candidates"
        );
        assert!(
            max_status_lookups <= 6,
            "one stage performed {max_status_lookups} historical status lookups"
        );
        let instrumentation = engine.instrumentation();
        assert!(instrumentation.external_flushes > 0);
        assert!(instrumentation.external_history_page_reads > 0);
        assert_eq!(instrumentation.scratch_syncs, 0);
        assert_eq!(instrumentation.batch_status_hot_entries, 0);
        assert_eq!(instrumentation.ready_payload_hot_entries, 0);
        assert!(instrumentation.document_hot_entries <= 65);
        engine
            .scratch
            .as_ref()
            .expect("store-backed engine scratch")
            .truncate_pages_for_test();
        let corrupt_left = engine.status();
        let corrupt_right = engine.status();
        assert!(matches!(
            corrupt_left.try_eq(&corrupt_right),
            Err(EngineError::Archive(_))
        ));
        assert!(matches!(
            engine.status().accepted_batch_ids(),
            Err(EngineError::Archive(_))
        ));
        engine.visible_documents.remove(&home);
        let tampered_materialization = engine.materialize_page(page);
        assert!(
            matches!(tampered_materialization, Err(EngineError::Archive(_))),
            "unexpected tampered materialization: {tampered_materialization:?}"
        );
        drop(engine);
        drop(writer);
        crate::test_support::remove_dir_all(root);
    }

    /// The clean write path has exactly three staging entry points.
    ///
    /// `stage_ready_internal` / `stage_ready_scratch` are reached from
    /// production only through `stage_ready_with_claim_source`, and that
    /// helper is called only by clean replay, clean commit, and the bounded
    /// acceptance of a clean prepared batch below the managed-local overlay. The
    /// legacy `stage_ready` / `stage_from_store` pair is `#[cfg(test)]` and
    /// cannot reach it at all. Widening this set widens the audited write
    /// path, so the set is pinned here rather than asserted in a comment.
    #[test]
    fn stage_ready_with_claim_source_has_exactly_the_three_clean_entry_points() {
        let source = include_str!("hot_engine.rs");
        let production = source
            .split("#[cfg(test)]\nmod validation_tests")
            .next()
            .expect("the hot-engine production half remains identifiable");
        let mut enclosing = "<file scope>";
        let mut definitions = Vec::new();
        let mut callers = Vec::new();
        for line in production.lines() {
            let trimmed = line.trim_start();
            if let Some(rest) = trimmed
                .strip_prefix("pub(crate) fn ")
                .or_else(|| trimmed.strip_prefix("pub fn "))
                .or_else(|| trimmed.strip_prefix("fn "))
            {
                enclosing = rest
                    .split(['(', '<'])
                    .next()
                    .expect("a function declaration names a function");
            }
            if !line.contains("stage_ready_with_claim_source(") {
                continue;
            }
            if trimmed.starts_with("fn ") || trimmed.starts_with("pub") {
                definitions.push(enclosing);
            } else {
                callers.push(enclosing);
            }
        }
        assert_eq!(
            definitions,
            vec!["stage_ready_with_claim_source"],
            "the claim-source staging helper must be declared exactly once"
        );
        assert_eq!(
            callers,
            vec![
                "replay_clean_committed_tail",
                "commit_clean_prepared",
                "accept_clean_prepared_below_managed_local_overlay",
            ],
            "only the three audited clean paths may stage with a claim source"
        );
        assert_eq!(
            production.matches("stage_ready_with_claim_source(").count(),
            4,
            "one declaration plus exactly three clean-path call sites"
        );
        for legacy in [
            "#[cfg(test)]\n    pub fn stage_ready(",
            "#[cfg(test)]\n    pub fn stage_from_store(",
        ] {
            assert!(
                production.contains(legacy),
                "the legacy staging entry point {legacy:?} must stay test-only"
            );
        }
    }

    #[test]
    fn no_store_page_name_preparation_source_guard_uses_direct_causal_heads() {
        let source = include_str!("hot_engine.rs");
        let prepare_start = source
            .find("    fn prepare_page_name_updates(")
            .expect("page-name prepare function remains present");
        let prepare_end = source[prepare_start..]
            .find("\n    fn commit_page_name_updates(")
            .expect("page-name prepare function remains bounded")
            + prepare_start;
        let prepare = &source[prepare_start..prepare_end];
        assert!(prepare.contains("derive_inline_causal_clock("));
        assert!(prepare.contains("if let Some(record) = candidate_clock"));
        assert!(
            !prepare.contains("collect_batch_ancestry")
                && !prepare.contains("unwrap_or(self.derive_inline_causal_clock"),
            "page-name preparation must use a lazy direct-head fallback"
        );

        let clock_start = source
            .find("    fn derive_inline_causal_clock(")
            .expect("inline causal-clock helper remains present");
        let clock_end = source[clock_start..]
            .find("\n    fn accepted_document_dependencies(")
            .expect("inline causal-clock helper remains bounded")
            + clock_start;
        let clock = &source[clock_start..clock_end];
        assert!(clock.contains("for parent in direct_causal_heads"));
        assert!(
            !clock.contains("collect_batch_ancestry") && !clock.contains("self.archive"),
            "inline causal-clock construction must use only direct-head lookups"
        );
    }

    #[test]
    fn ordinary_identity_and_path_admission_never_walks_batch_ancestry() {
        let source = include_str!("hot_engine.rs");
        let function = |name: &str, next: &str| {
            let ordinary_marker = format!("    fn {name}(");
            let generic_marker = format!("    fn {name}<");
            let start = source
                .find(&ordinary_marker)
                .or_else(|| source.find(&generic_marker))
                .unwrap_or_else(|| panic!("{name} remains present"));
            let tail = &source[start..];
            let end = [
                format!("\n    fn {next}("),
                format!("\n    pub(crate) fn {next}("),
                format!("\n    pub fn {next}("),
            ]
            .iter()
            .filter_map(|marker| tail.find(marker))
            .min()
            .unwrap_or_else(|| panic!("{name} remains bounded by {next}"))
                + start;
            &source[start..end]
        };

        for (name, body) in [
            (
                "prepare_portable_path_updates",
                function(
                    "prepare_portable_path_updates",
                    "commit_portable_path_updates",
                ),
            ),
            (
                "validate_and_prepare_semantic_roles_and_block_homes",
                function(
                    "validate_and_prepare_semantic_roles_and_block_homes",
                    "block_home_claims_many",
                ),
            ),
            (
                "logseq_claim_evidence_at_frontier",
                function(
                    "logseq_claim_evidence_at_frontier",
                    "resolve_logseq_uuid_from_documents",
                ),
            ),
        ] {
            assert!(
                !body.contains("collect_batch_ancestry"),
                "ordinary {name} must answer causality from sparse direct-head clocks"
            );
        }
        let portable = function(
            "prepare_portable_path_updates",
            "commit_portable_path_updates",
        );
        assert!(portable.contains("portable_path_records_many(&requested)"));
        assert!(
            !portable.contains("clone_validation_document")
                && !portable.contains("validate_catalog"),
            "bounded path admission must trust the authenticated requested-key index rather than re-prove whole-catalog equivalence"
        );
        let linearity = function(
            "refresh_nonlinear_watermark",
            "accepted_nonlinear_batch_ids",
        );
        assert!(linearity.contains("accepted_batch_count()"));
        assert!(linearity.contains("accepted_batch_id_at(sequence)"));
        assert!(
            !linearity.contains("accepted_batches()")
                && !linearity.contains("accepted_batch_ids()")
                && !linearity.contains("collect_batch_ancestry"),
            "ordinary linearity refresh must inspect only newly accepted sequence points"
        );
        let retained_catalog = function("retained_accepted_document", "retain_accepted_document");
        assert!(
            !retained_catalog.contains("DecodedDocumentVersion::of"),
            "bounded retained-catalog reuse must not recompute the graph-sized Loro version"
        );
        let bootstrap_chunk = function("materialize_chunk", "materialize_pages");
        assert!(
            !bootstrap_chunk.contains("DecodedDocumentVersion::of")
                && !bootstrap_chunk.contains("validate_catalog"),
            "each bootstrap chunk must reuse the catalog proof established once at materializer construction"
        );
        let bootstrap_constructor = function(
            "bootstrap_bulk_materializer_with_lookup_budget",
            "materialize_page_at_accepted_root",
        );
        assert!(
            bootstrap_constructor.contains("retain_accepted_document("),
            "activation/rebuild must seed the retained catalog instead of making the first ordinary derivative decode it again"
        );
        let local_predecessor = function(
            "managed_local_projection_predecessor",
            "capture_author_transaction",
        );
        assert!(
            local_predecessor.contains("latest_projection")
                && local_predecessor.contains(".get(&(page_id, path.clone()))")
        );
        assert!(
            !local_predecessor.contains("entries.iter()"),
            "composing queued local edits must point-read the latest projection rather than scan the pending prefix"
        );
        let managed_authority = function(
            "validate_managed_local_projection_authority",
            "validate_clean_manifest_projection_authority",
        );
        assert!(managed_authority.contains(".entry(sequence, batch_id)"));
        assert!(
            !managed_authority.contains("local_overlay.entries")
                && !managed_authority.contains("entries.iter()"),
            "revalidating queued local authority must point-read its batch index"
        );
        for drain in [
            function("drain_staged", "drain_blocked_evidence"),
            function("drain_blocked_evidence", "incomplete_staged_disposition"),
        ] {
            assert!(drain.contains("self.staged_batches.iter()"));
            assert!(
                !drain.contains("self.statuses.iter()"),
                "ordinary admission must visit live staged work, not lifetime status history"
            );
        }
        let acceptance = function("prepare_acceptance_evidence", "commit_acceptance_evidence");
        assert!(acceptance.contains("ephemeral_accepted_document_root.with_upserts"));
        assert!(acceptance.contains("ephemeral_accepted_batch_root"));
        assert!(acceptance.contains(".with_upserts"));
        assert!(
            !acceptance.contains("accepted_frontier.clone()")
                && !acceptance.contains("ephemeral_accepted_batch_entries.clone()")
                && !acceptance.contains("authenticated_document_map_root("),
            "one accepted operation must path-copy exact authenticated roots, not rebuild session history"
        );

        let production = source
            .split("#[cfg(test)]\nmod validation_tests")
            .next()
            .expect("production half remains identifiable");
        assert_eq!(
            production.matches("collect_batch_ancestry(").count(),
            3,
            "two full ancestry call sites plus their definition stay confined to reconstruction paths"
        );
    }

    #[test]
    fn run_local_authenticated_map_matches_canonical_full_rebuild() {
        let mut incremental = RunLocalAuthenticatedMap::default();
        let mut canonical = BTreeMap::<BatchId, ContentDigest>::new();
        for ordinal in [7_u128, 2, 19, 1, 11, 5, 23, 3, 17, 13] {
            let batch_id = BatchId::from_uuid(Uuid::from_u128(0xa9000 + ordinal));
            let digest = ContentDigest::of(format!("accepted-{ordinal}").as_bytes());
            incremental.upsert(batch_id.as_uuid().into_bytes(), digest);
            canonical.insert(batch_id, digest);
            let entries = canonical
                .iter()
                .map(|(batch_id, digest)| (*batch_id, *digest))
                .collect::<Vec<_>>();
            let (root_key, root_digest) = authenticated_map_root(&entries).unwrap();
            assert_eq!(incremental.count, entries.len() as u64);
            assert_eq!(incremental.root_key(), root_key);
            assert_eq!(incremental.root_digest(), root_digest);
        }

        let replaced = BatchId::from_uuid(Uuid::from_u128(0xa9000 + 11));
        let replacement_digest = ContentDigest::of(b"accepted-replacement");
        incremental.upsert(replaced.as_uuid().into_bytes(), replacement_digest);
        canonical.insert(replaced, replacement_digest);
        let entries = canonical.into_iter().collect::<Vec<_>>();
        let (root_key, root_digest) = authenticated_map_root(&entries).unwrap();
        assert_eq!(incremental.count, entries.len() as u64);
        assert_eq!(incremental.root_key(), root_key);
        assert_eq!(incremental.root_digest(), root_digest);
    }

    #[test]
    fn no_store_local_page_name_duplicates_are_rejected_without_mutation_at_acceptance() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(8_300));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(8_301));
        let lineage = LineageDigest::of(b"no-store-page-name-author-preflight");
        let mut intra_engine = ShardedHotEngine::new(workspace, lineage, catalog);

        let intra_batch = intra_engine
            .prepare_bootstrap_transaction(
                test_author(8_310, 8_310),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: PageId::from_uuid(Uuid::from_u128(8_311)),
                        home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_312)),
                        name: LogicalPageName::parse("Duplicate").unwrap(),
                        path: ManagedPath::parse("pages/left.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: PageId::from_uuid(Uuid::from_u128(8_313)),
                        home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_314)),
                        name: LogicalPageName::parse("duplicate").unwrap(),
                        path: ManagedPath::parse("pages/right.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        let prior_page_names = intra_engine.ephemeral_page_names.clone();
        assert!(matches!(
            intra_engine
                .stage_ready(ValidatedBatch::new(intra_batch))
                .disposition(),
            BatchDisposition::Rejected {
                error: EngineError::InvalidTransaction(_),
            }
        ));
        assert_eq!(intra_engine.ephemeral_page_names, prior_page_names);
        assert_eq!(
            intra_engine.workspace_status(),
            WorkspaceStatus::Operational
        );

        let mut engine = ShardedHotEngine::new(workspace, lineage, catalog);
        let first = engine
            .prepare_bootstrap_transaction(
                test_author(8_320, 8_320),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: PageId::from_uuid(Uuid::from_u128(8_321)),
                    home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_322)),
                    name: LogicalPageName::parse("Owned").unwrap(),
                    path: ManagedPath::parse("pages/owned.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine.stage_ready(ValidatedBatch::new(first)).disposition(),
            BatchDisposition::Accepted { .. }
        ));
        assert_eq!(engine.ephemeral_page_names.record_count(), 1);
        let prior_page_names = engine.ephemeral_page_names.clone();
        let duplicate = engine
            .prepare_bootstrap_transaction(
                test_author(8_323, 8_323),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: PageId::from_uuid(Uuid::from_u128(8_324)),
                    home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_325)),
                    name: LogicalPageName::parse("OWNED").unwrap(),
                    path: ManagedPath::parse("pages/other.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(duplicate))
                .disposition(),
            BatchDisposition::Rejected {
                error: EngineError::InvalidTransaction(_),
            }
        ));
        assert_eq!(engine.ephemeral_page_names, prior_page_names);
        assert_eq!(engine.workspace_status(), WorkspaceStatus::Operational);
    }

    #[test]
    fn no_store_concurrent_page_name_claims_quarantine_identically_in_both_orders() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(8_400));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(8_401));
        let lineage = LineageDigest::of(b"no-store-page-name-delivery-order");
        let left_author = ShardedHotEngine::new(workspace, lineage, catalog);
        let right_author = ShardedHotEngine::new(workspace, lineage, catalog);
        let left = left_author
            .prepare_bootstrap_transaction(
                test_author(8_410, 8_410),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: PageId::from_uuid(Uuid::from_u128(8_411)),
                    home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_412)),
                    name: LogicalPageName::parse("Concurrent Shared").unwrap(),
                    path: ManagedPath::parse("pages/left.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        let right = right_author
            .prepare_bootstrap_transaction(
                test_author(8_420, 8_420),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: PageId::from_uuid(Uuid::from_u128(8_421)),
                    home_document_id: DocumentId::from_uuid(Uuid::from_u128(8_422)),
                    name: LogicalPageName::parse("concurrent shared").unwrap(),
                    path: ManagedPath::parse("pages/right.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();

        let deliver = |first: PreparedBatch, second: PreparedBatch| {
            let mut receiver = ShardedHotEngine::new(workspace, lineage, catalog);
            assert!(matches!(
                receiver
                    .stage_ready(ValidatedBatch::new(first))
                    .disposition(),
                BatchDisposition::Accepted { .. }
            ));
            let prior_page_names = receiver.ephemeral_page_names.clone();
            let second_outcome = receiver.stage_ready(ValidatedBatch::new(second));
            assert!(
                matches!(second_outcome.disposition(), BatchDisposition::Quarantined),
                "unexpected second disposition: {:?}",
                second_outcome.disposition()
            );
            assert_eq!(receiver.ephemeral_page_names, prior_page_names);
            assert!(receiver.fatal_evidence_handle().is_none());
            assert!(matches!(
                receiver.workspace_status(),
                WorkspaceStatus::Blocked(_)
            ));
            receiver.page_name_conflicts()[0].encode().unwrap()
        };
        let left_then_right = deliver(left.clone(), right.clone());
        let right_then_left = deliver(right, left);
        assert_eq!(left_then_right, right_then_left);
    }

    #[test]
    fn store_backed_page_name_candidate_tracks_names_not_paths_and_requires_exact_checkpoint() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(8_500));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(8_501));
        let first_page = PageId::from_uuid(Uuid::from_u128(8_502));
        let second_page = PageId::from_uuid(Uuid::from_u128(8_503));
        let first_home = DocumentId::from_uuid(Uuid::from_u128(8_504));
        let second_home = DocumentId::from_uuid(Uuid::from_u128(8_505));
        let lineage = LineageDigest::of(b"page-name-acceptance-seam");
        let root =
            std::env::temp_dir().join(format!("tine-oplog-page-name-seam-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let archive_path = root.join("archive");
        let writer = ObjectStore::open(&archive_path, workspace).unwrap();
        let reader = ObjectStore::open(&archive_path, workspace).unwrap();
        let mut engine = ShardedHotEngine::with_archive_store(reader, lineage, catalog);

        let publish = |engine: &mut ShardedHotEngine,
                       author: AuthorBatch,
                       operations: Vec<SemanticOperation>| {
            let prepared = engine
                .prepare_bootstrap_transaction(
                    author,
                    &OperationTransaction::new(operations).unwrap(),
                )
                .unwrap();
            writer
                .publish_bootstrap_prepared_for_test(&prepared)
                .unwrap();
            assert!(matches!(
                engine
                    .stage_archive_batch(prepared.manifest().batch_id())
                    .unwrap()
                    .disposition(),
                BatchDisposition::Accepted { .. }
            ));
        };

        publish(
            &mut engine,
            test_author(8_510, 8_510),
            vec![SemanticOperation::CreatePage {
                page_id: first_page,
                home_document_id: first_home,
                name: LogicalPageName::parse("Original Name").unwrap(),
                path: ManagedPath::parse("pages/original.md").unwrap(),
                kind: ManagedTextKind::Page,
            }],
        );
        let created_name_root = engine.page_name_index_root().unwrap().clone();
        let created_path_root = engine.portable_path_index_root().unwrap();
        assert_eq!(created_name_root.entry_count(), 1);

        publish(
            &mut engine,
            test_author(8_511, 8_510),
            vec![SemanticOperation::EditPagePath {
                page_id: first_page,
                path: ManagedPath::parse("deep/physical/move.md").unwrap(),
            }],
        );
        assert_eq!(engine.page_name_index_root().unwrap(), &created_name_root);
        assert_ne!(
            engine.portable_path_index_root().unwrap(),
            created_path_root
        );
        let moved_path_root = engine.portable_path_index_root().unwrap();

        publish(
            &mut engine,
            test_author(8_512, 8_510),
            vec![SemanticOperation::RenamePagesAndRewriteReferrers {
                page_changes: vec![PageRename {
                    page_id: first_page,
                    new_name: LogicalPageName::parse("Renamed").unwrap(),
                    new_path: ManagedPath::parse("deep/physical/move.md").unwrap(),
                }],
                block_rewrites: Vec::new(),
                page_preamble_rewrites: Vec::new(),
            }],
        );
        assert_ne!(engine.page_name_index_root().unwrap(), &created_name_root);
        assert_eq!(engine.portable_path_index_root().unwrap(), moved_path_root);
        let renamed_key = LogicalPageName::parse("Renamed").unwrap().key_digest();
        assert_eq!(
            engine
                .page_name_index
                .as_ref()
                .unwrap()
                .lookup(engine.page_name_index_root().unwrap(), renamed_key)
                .unwrap()
                .unwrap()
                .occupied()
                .unwrap()
                .page_id(),
            first_page
        );

        publish(
            &mut engine,
            test_author(8_513, 8_510),
            vec![SemanticOperation::DeletePage {
                page_id: first_page,
            }],
        );
        publish(
            &mut engine,
            test_author(8_514, 8_510),
            vec![SemanticOperation::CreatePage {
                page_id: second_page,
                home_document_id: second_home,
                name: LogicalPageName::parse("Renamed").unwrap(),
                path: ManagedPath::parse("pages/reused.md").unwrap(),
                kind: ManagedTextKind::Page,
            }],
        );
        assert_eq!(
            engine
                .page_name_index
                .as_ref()
                .unwrap()
                .lookup(engine.page_name_index_root().unwrap(), renamed_key)
                .unwrap()
                .unwrap()
                .occupied()
                .unwrap()
                .page_id(),
            second_page
        );

        let authoritative_root = engine.page_name_index_root().unwrap().clone();
        let carried = engine
            .prepare_bootstrap_transaction(
                test_author(8_515, 8_510),
                &OperationTransaction::new(vec![
                    SemanticOperation::RenamePagesAndRewriteReferrers {
                        page_changes: vec![PageRename {
                            page_id: second_page,
                            new_name: LogicalPageName::parse("Carried Proof Tamper").unwrap(),
                            new_path: ManagedPath::parse("pages/reused.md").unwrap(),
                        }],
                        block_rewrites: Vec::new(),
                        page_preamble_rewrites: Vec::new(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        writer
            .publish_bootstrap_prepared_for_test(&carried)
            .unwrap();
        let exact_root = engine.scratch_roots.external_document_state_root.clone();
        engine.scratch_roots.external_document_state_root = Default::default();
        engine
            .catalog_checkpoint_loads
            .set(CatalogCheckpointLoadStats::default());
        let tampered = engine
            .stage_archive_batch(carried.manifest().batch_id())
            .unwrap();
        assert!(matches!(
            tampered.disposition(),
            BatchDisposition::Rejected {
                error: EngineError::Archive(_),
            }
        ));
        assert_eq!(
            engine.catalog_checkpoint_loads.get(),
            CatalogCheckpointLoadStats {
                authenticated_exact: 1,
                current: 0,
            }
        );
        let refused = engine
            .prepare_bootstrap_transaction(
                test_author(8_516, 8_510),
                &OperationTransaction::new(vec![
                    SemanticOperation::RenamePagesAndRewriteReferrers {
                        page_changes: vec![PageRename {
                            page_id: second_page,
                            new_name: LogicalPageName::parse("Must Not Mint").unwrap(),
                            new_path: ManagedPath::parse("pages/reused.md").unwrap(),
                        }],
                        block_rewrites: Vec::new(),
                        page_preamble_rewrites: Vec::new(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        writer
            .publish_bootstrap_prepared_for_test(&refused)
            .unwrap();
        assert!(matches!(
            engine
                .stage_archive_batch(refused.manifest().batch_id())
                .unwrap()
                .disposition(),
            BatchDisposition::Rejected {
                error: EngineError::Archive(_),
            }
        ));
        assert_eq!(engine.page_name_root, authoritative_root);
        assert_eq!(engine.workspace_status(), WorkspaceStatus::Operational);
        engine.scratch_roots.external_document_state_root = exact_root;

        drop(engine);
        drop(writer);
        crate::test_support::remove_dir_all(root);
    }

    #[test]
    fn concurrent_page_name_claims_quarantine_identically_in_both_delivery_orders() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(8_600));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(8_601));
        let seed_page = PageId::from_uuid(Uuid::from_u128(8_602));
        let seed_home = DocumentId::from_uuid(Uuid::from_u128(8_603));
        let left_page = PageId::from_uuid(Uuid::from_u128(8_604));
        let left_home = DocumentId::from_uuid(Uuid::from_u128(8_605));
        let right_page = PageId::from_uuid(Uuid::from_u128(8_606));
        let right_home = DocumentId::from_uuid(Uuid::from_u128(8_607));
        let lineage = LineageDigest::of(b"page-name-delivery-order");
        let root =
            std::env::temp_dir().join(format!("tine-oplog-page-name-order-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let archive_path = root.join("archive");
        let writer = ObjectStore::open(&archive_path, workspace).unwrap();

        let mut base_author = ShardedHotEngine::with_archive_store(
            ObjectStore::open(&archive_path, workspace).unwrap(),
            lineage,
            catalog,
        );
        let base = base_author
            .prepare_bootstrap_transaction(
                test_author(8_610, 8_610),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: seed_page,
                    home_document_id: seed_home,
                    name: LogicalPageName::parse("Seed").unwrap(),
                    path: ManagedPath::parse("pages/seed.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        writer.publish_bootstrap_prepared_for_test(&base).unwrap();
        assert!(matches!(
            base_author
                .stage_archive_batch(base.manifest().batch_id())
                .unwrap()
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let right_author =
            independent_archive_author(&root, "right-author", workspace, lineage, catalog, &base);
        let left = base_author
            .prepare_bootstrap_transaction(
                test_author(8_611, 8_611),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: left_page,
                    home_document_id: left_home,
                    name: LogicalPageName::parse("Concurrent Shared").unwrap(),
                    path: ManagedPath::parse("pages/left.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        let right = right_author
            .prepare_bootstrap_transaction(
                test_author(8_612, 8_612),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: right_page,
                    home_document_id: right_home,
                    name: LogicalPageName::parse("concurrent shared").unwrap(),
                    path: ManagedPath::parse("pages/right.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        writer.publish_bootstrap_prepared_for_test(&left).unwrap();
        writer.publish_bootstrap_prepared_for_test(&right).unwrap();

        let deliver = |first: BatchId, second: BatchId| {
            let mut receiver = ShardedHotEngine::with_archive_store(
                ObjectStore::open(&archive_path, workspace).unwrap(),
                lineage,
                catalog,
            );
            assert!(matches!(
                receiver
                    .stage_archive_batch(base.manifest().batch_id())
                    .unwrap()
                    .disposition(),
                BatchDisposition::Accepted { .. }
            ));
            receiver
                .catalog_checkpoint_loads
                .set(CatalogCheckpointLoadStats::default());
            assert!(matches!(
                receiver.stage_archive_batch(first).unwrap().disposition(),
                BatchDisposition::Accepted { .. }
            ));
            assert_eq!(
                receiver.catalog_checkpoint_loads.get(),
                CatalogCheckpointLoadStats {
                    authenticated_exact: 1,
                    current: 1,
                },
                "accepted page-name replay must retain bounded exact and current catalog authentication"
            );
            let prior_root = receiver.page_name_index_root().unwrap().clone();
            receiver
                .catalog_checkpoint_loads
                .set(CatalogCheckpointLoadStats::default());
            assert!(matches!(
                receiver.stage_archive_batch(second).unwrap().disposition(),
                BatchDisposition::Quarantined
            ));
            assert_eq!(
                receiver.catalog_checkpoint_loads.get(),
                CatalogCheckpointLoadStats {
                    authenticated_exact: 1,
                    current: 1,
                },
                "divergent current catalog must retain its authenticated current fallback"
            );
            assert_eq!(receiver.page_name_root, prior_root);
            assert!(matches!(
                receiver.status().workspace(),
                WorkspaceStatus::Blocked(_)
            ));
            assert!(receiver.fatal_evidence_handle().is_none());
            assert!(receiver.fatal_evidence_page(None, 1).unwrap().is_none());
            receiver.page_name_conflicts()[0].encode().unwrap()
        };
        let left_then_right = deliver(left.manifest().batch_id(), right.manifest().batch_id());
        let right_then_left = deliver(right.manifest().batch_id(), left.manifest().batch_id());
        assert_eq!(left_then_right, right_then_left);
        assert_eq!(ENGINE_HISTORY_SCHEMA_VERSION, 14);
        assert_eq!(
            super::super::page_name_index::PAGE_NAME_OWNERSHIP_ROOT_SCHEMA_VERSION,
            2,
            "the delivery-order evidence deliberately pins the current page-name root schema"
        );
        let reopened = ShardedHotEngine::with_archive_store(
            ObjectStore::open(&archive_path, workspace).unwrap(),
            lineage,
            catalog,
        );
        assert_eq!(reopened.workspace_status(), WorkspaceStatus::Operational);
        assert!(reopened.fatal_evidence_handle().is_none());
        assert!(reopened.fatal_evidence_page(None, 1).unwrap().is_none());

        drop(base_author);
        drop(right_author);
        drop(reopened);
        drop(writer);
        crate::test_support::remove_dir_all(root);
    }

